// Nightly enumerator, Azure.Storage.Blobs (v12) SDK
var states = BlobStates.All;

await foreach (BlobItem item in container.GetBlobsAsync(states: states))
{
    BlobClient bc = container.GetBlobClient(item.Name);
    await bc.DownloadToAsync(Path.Combine(targetFolder, item.Name));
}

